			json.writeStartObject();
			json.writeStringField("id", job.id);
			json.writeStringField("operation", job.operation);
			json.writeStringField("state", job.state);
			json.writeStringField("startedAt", job.startedAt.toString());
			json.writeStringField("finishedAt", job.finishedAt == null ? null : job.finishedAt.toString());
			json.writeStringField("message", job.message);
			json.writeStringField("targetRepositoryId", job.target);
			json.writeEndObject();
